for item in items:
    if item == target:
        return True

low, high = 0, len(items) - 1
while low <= high:
    mid = (low + high) // 2
    if items[mid] == target:
        return mid
    if items[mid] < target:
        low = mid + 1
    else:
        high = mid - 1

for i in items:
    for j in items:
        if i + j == target:
            return True
